// @ts-nocheck -- desktop bridge additions are generated by Electron preload.
import {useEffect,useState} from 'react';
import {RemoteQrDialog} from './RemoteQrDialog';
import {useLiveAnnotations} from './LiveAnnotations';

export interface PersonalMonitor{id:string;slug:string;name:string;sourceType:'main'|'stage'|'livestream';layout:'mirror'|'current-next';defaultLanguage:'de'|'en';showCurrent:boolean;showNext:boolean;showClock:boolean;showCountdown:boolean;showNotes:boolean;showOrderOfService:boolean;enabled:boolean;connected?:number}
export interface RemoteDevice{id:string;name:string;permissionRole:'view'|'preacher'|'control'|'advanced';preferredLanguage:'de'|'en';permissions:string[];token:string;revoked:boolean;lastSeenAt?:string}
export interface RemoteServiceState{active:boolean;address:string;port:number;monitors:PersonalMonitor[];remotes:RemoteDevice[]}
const empty:RemoteServiceState={active:false,address:'127.0.0.1',port:43170,monitors:[],remotes:[]};
const rolePermissions:Record<RemoteDevice['permissionRole'],string[]>={view:['remote.view'],preacher:['remote.view','remote.viewNotes'],control:['remote.view','remote.next','remote.previous','remote.selectSlide','remote.selectItem','remote.quickScreen'],advanced:['remote.view','remote.viewNotes','remote.next','remote.previous','remote.selectSlide','remote.selectItem','remote.quickScreen','remote.stageMessage','remote.viewRecording']};

export function RemoteCenter(){
  const [state,setState]=useState(empty),[mode,setMode]=useState<'overview'|'monitor'|'remote'>('overview'),[name,setName]=useState('Prediger Monitor'),[slug,setSlug]=useState('prediger'),[source,setSource]=useState<PersonalMonitor['sourceType']>('stage'),[role,setRole]=useState<RemoteDevice['permissionRole']>('preacher'),[language,setLanguage]=useState<'de'|'en'>('de');
  const [qr,setQr]=useState<{name:string;url:string}|null>(null);
  const [allowAnnotations,setAllowAnnotations]=useState(false),[layout,setLayout]=useState<PersonalMonitor['layout']>('current-next'),[showNotes,setShowNotes]=useState(false),[showOrder,setShowOrder]=useState(false);
  const refresh=()=>void window.desktop?.remote.get().then(setState);
  useEffect(()=>{refresh()},[]);
  const base=`http://${state.address}:${state.port}`;
  async function addMonitor(){await window.desktop?.remote.saveMonitor({id:crypto.randomUUID(),slug:slug.toLowerCase().replace(/[^a-z0-9-]/g,'-').replace(/^-+|-+$/g,''),name,sourceType:source,layout,defaultLanguage:language,showCurrent:true,showNext:true,showClock:true,showCountdown:true,showNotes,showOrderOfService:showOrder,enabled:true});setMode('overview');refresh()}
  async function addRemote(){const result=await window.desktop?.remote.createSession({name,permissionRole:role,preferredLanguage:language,permissions:[...rolePermissions[role],...(allowAnnotations?['remote.annotate']:[])]});setMode('overview');await refresh();if(result)setQr({name:result.name,url:`${base}/remote/${result.token}`})}
  const copy=(value:string)=>void navigator.clipboard.writeText(value);
  return <><section className="remote-center"><h3>Anzeige &amp; Web-Steuerung</h3><p>Personal Monitore sind dauerhaft erreichbare, reine Anzeigen. Web-Steuerungen erhalten eine individuelle widerrufbare Sitzung und nur ausdrücklich freigegebene Befehle.</p><div className={`remote-service ${state.active?'online':'offline'}`}><span/><div><b>{state.active?'Remote-Service bereit':'Remote-Service nicht verfügbar'}</b><small>{base} · lokales Netzwerk</small></div><button onClick={refresh}>Status prüfen</button></div>{mode==='overview'?<><div className="remote-actions"><button className="primary" onClick={()=>{setName('Prediger Monitor');setSlug('prediger');setMode('monitor')}}>+ Personal Monitor</button><button onClick={()=>{setName('iPad Prediger');setAllowAnnotations(false);setMode('remote')}}>+ Gerät verbinden</button></div><h4>Personal Monitore</h4><div className="remote-list">{state.monitors.map(m=><article key={m.id}><span className="material-symbols-outlined">monitor</span><div><b>{m.name}</b><small>{m.sourceType.toUpperCase()} · /monitor/{m.slug} · {m.connected??0} verbunden</small></div><button onClick={()=>copy(`${base}/monitor/${m.slug}`)}>URL kopieren</button><button onClick={()=>setQr({name:m.name,url:`${base}/monitor/${m.slug}`})}>QR-Code</button><button onClick={()=>void window.desktop?.openExternal(`${base}/monitor/${m.slug}`)}>Vorschau</button><button className="danger" onClick={async()=>{if(confirm(`Personal Monitor „${m.name}“ deaktivieren?`)){await window.desktop?.remote.removeMonitor(m.id);refresh()}}}>Deaktivieren</button></article>)||null}{!state.monitors.length&&<p>Noch kein Personal Monitor eingerichtet.</p>}</div><button onClick={()=>{useLiveAnnotations.setState({state:null});void window.desktop?.sendAnnotations?.(null)}}>Live-Markierungen löschen</button><h4>Web-Steuerungen</h4><div className="remote-list">{state.remotes.filter(r=>!r.revoked).map(r=><article key={r.id}><span className="material-symbols-outlined">phone_iphone</span><div><b>{r.name}</b><small>{r.permissionRole.toUpperCase()} · {r.preferredLanguage==='de'?'Deutsch':'English'} · sichere Einzelsitzung</small></div><button onClick={()=>copy(`${base}/remote/${r.token}`)}>URL kopieren</button><button onClick={()=>setQr({name:r.name,url:`${base}/remote/${r.token}`})}>QR-Code</button><button className="danger" onClick={async()=>{await window.desktop?.remote.revokeSession(r.id);refresh()}}>Zugriff widerrufen</button></article>)}{!state.remotes.some(r=>!r.revoked)&&<p>Noch keine Web-Steuerung freigegeben.</p>}</div></>:mode==='monitor'?<div className="remote-form"><h4>Personal Monitor erstellen</h4><label>Name<input value={name} onChange={e=>setName(e.target.value)}/></label><label>URL-Kennung<input value={slug} onChange={e=>setSlug(e.target.value)}/><small>Die URL bleibt bei Gottesdienst-, Benutzer- und Programmwechsel gleich.</small></label><label>Ansicht<select value={layout} onChange={e=>setLayout(e.target.value)}><option value="current-next">Aktuelle und nächste Folie</option><option value="mirror">Große aktuelle Folie</option></select></label><label><input type="checkbox" checked={showNotes} onChange={e=>setShowNotes(e.target.checked)}/>Notizen anzeigen</label><label><input type="checkbox" checked={showOrder} onChange={e=>setShowOrder(e.target.checked)}/>Ablauf anzeigen</label><label>Quelle<select value={source} onChange={e=>setSource(e.target.value as PersonalMonitor['sourceType'])}><option value="stage">STAGE – Prediger</option><option value="main">MAIN</option><option value="livestream">LIVESTREAM</option></select></label><label>Sprache<select value={language} onChange={e=>setLanguage(e.target.value as 'de'|'en')}><option value="de">Deutsch</option><option value="en">English</option></select></label><footer><button onClick={()=>setMode('overview')}>Abbrechen</button><button className="primary" disabled={!name.trim()||!slug.trim()} onClick={()=>void addMonitor()}>Erstellen</button></footer></div>:<div className="remote-form"><h4>Web-Steuerung freigeben</h4><label>Gerätename<input value={name} onChange={e=>setName(e.target.value)}/></label><label>Berechtigung<select value={role} onChange={e=>setRole(e.target.value as RemoteDevice['permissionRole'])}><option value="view">Nur Anzeige</option><option value="preacher">Prediger</option><option value="control">Steuerung</option><option value="advanced">Erweiterte Steuerung</option></select></label><label>Sprache<select value={language} onChange={e=>setLanguage(e.target.value as 'de'|'en')}><option value="de">Deutsch</option><option value="en">English</option></select></label><label><input type="checkbox" checked={allowAnnotations} onChange={e=>setAllowAnnotations(e.target.checked)}/>Live-Markierungen auf allen Ausgaben erlauben</label><p>Markierungen erscheinen auch auf MAIN. Ein reiner Monitor-Link bleibt schreibgeschützt. Nach dem Erstellen erscheint ein QR-Code. ON AIR/OFF AIR bleibt der Regie vorbehalten.</p><footer><button onClick={()=>setMode('overview')}>Abbrechen</button><button className="primary" disabled={!name.trim()} onClick={()=>void addRemote()}>Verbindung starten</button></footer></div>}</section>{qr&&<RemoteQrDialog {...qr} onClose={()=>setQr(null)}/>}</>
}
